package dev.brl.glyph;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/**
 * Host checks for the website parity port. The fixtures are generated by
 * .research/.ref/reference.mjs from the same PCM using the real Meyda package
 * and the site's generators, so these are reference comparisons rather than
 * self-consistency checks.
 */
public final class AutoGenTests {

    private static int checks;
    private static final int SAMPLE_RATE = 48000;

    private AutoGenTests() {
    }

    public static void main(String[] args) throws Exception {
        Path root = Paths.get("tests", "fixtures");
        short[] pcm = loadPcm(root.resolve("autogen_input.pcm"));
        check(pcm.length == 57600, "reference PCM is 1.2 seconds at 48 kHz");

        int[][] beats = render(pcm, AutoGen.MODE_BEATS);
        int[][] smooth = render(pcm, AutoGen.MODE_SMOOTH);
        int[][] frequency = render(pcm, AutoGen.MODE_FREQUENCY);
        int[][] pattern = render(pcm, AutoGen.MODE_PATTERN);

        compare("beats", beats, loadReference(root.resolve("autogen_beats.txt")));
        compare("smooth", smooth, loadReference(root.resolve("autogen_smooth.txt")));
        compare("frequency", frequency, loadReference(root.resolve("autogen_frequency.txt")));
        compare("pattern", pattern, loadReference(root.resolve("autogen_pattern.txt")));

        int[][] beatsAgain = render(pcm, AutoGen.MODE_BEATS);
        check(Arrays.deepEquals(beats, beatsAgain), "Beats is deterministic for a fixed seed");

        int[][] patternAgain = render(pcm, AutoGen.MODE_PATTERN);
        check(Arrays.deepEquals(pattern, patternAgain), "Pattern is deterministic for a fixed seed");

        checkHasHeavyFrame(beats, "Beats has the single-LED heavy-beat path");
        checkAllLitModes(beats, "Beats");
        checkAllLitModes(smooth, "Smooth");
        checkAllLitModes(frequency, "Frequency");
        checkAllLitModes(pattern, "Pattern");

        System.out.println("PASS: " + checks + " auto-gen assertions");
    }

    private static int[][] render(short[] pcm, int mode) {
        int[][] frames = AutoGen.render(pcm, pcm.length, SAMPLE_RATE, mode);
        check(frames.length == 70, AutoGenModeName.name(mode) + " has 70 website frames");
        for (int frame = 0; frame < frames.length; frame++) {
            check(frames[frame].length == GlyphLayout.LEDS,
                    AutoGenModeName.name(mode) + " frame has 36 columns");
            for (int value : frames[frame]) {
                check(value >= 0 && value <= GlyphLayout.MAX_VALUE,
                        AutoGenModeName.name(mode) + " value fits 0..255");
            }
        }
        return frames;
    }

    private static short[] loadPcm(Path path) throws Exception {
        byte[] bytes = Files.readAllBytes(path);
        short[] pcm = new short[bytes.length / 2];
        for (int i = 0; i < pcm.length; i++) {
            int low = bytes[i * 2] & 0xff;
            int high = bytes[i * 2 + 1];
            pcm[i] = (short) ((high << 8) | low);
        }
        return pcm;
    }

    private static int[][] loadReference(Path path) throws Exception {
        List<int[]> rows = new ArrayList<>();
        for (String line : Files.readAllLines(path)) {
            if (line.trim().isEmpty()) {
                continue;
            }
            String[] cells = line.split(",");
            int[] row = new int[cells.length];
            for (int i = 0; i < cells.length; i++) {
                row[i] = Integer.parseInt(cells[i].trim());
            }
            rows.add(row);
        }
        return rows.toArray(new int[rows.size()][]);
    }

    private static void compare(String mode, int[][] actual, int[][] expected) {
        check(actual.length == expected.length, mode + " matches reference frame count");
        int maxDiff = 0;
        int mismatches = 0;
        int differingFrames = 0;
        int printed = 0;
        for (int frame = 0; frame < Math.min(actual.length, expected.length); frame++) {
            check(actual[frame].length == expected[frame].length,
                    mode + " frame " + frame + " matches reference width");
            boolean rowDiff = false;
            for (int led = 0; led < Math.min(actual[frame].length, expected[frame].length); led++) {
                int diff = Math.abs(actual[frame][led] - expected[frame][led]);
                if (diff > maxDiff) {
                    maxDiff = diff;
                }
                if (diff != 0) {
                    if (printed < 16) {
                        System.out.println("  " + mode + " frame=" + frame + " led=" + led
                                + " actual=" + actual[frame][led]
                                + " expected=" + expected[frame][led]);
                        printed++;
                    }
                    mismatches++;
                    rowDiff = true;
                }
            }
            if (rowDiff) {
                differingFrames++;
            }
        }
        System.out.println(mode + ": frames=" + actual.length
                + " maxDiff=" + maxDiff + " differingValues=" + mismatches
                + " differingFrames=" + differingFrames);
        check(maxDiff <= 2, mode + " stays within two 0..255 steps of the website");
    }

    private static void checkHasHeavyFrame(int[][] frames, String message) {
        boolean found = false;
        for (int[] frame : frames) {
            int lit = 0;
            for (int value : frame) {
                if (value > 0) {
                    lit++;
                }
            }
            if (lit == 1 && contains(frame, 255)) {
                found = true;
            }
        }
        check(found, message);
    }

    private static boolean contains(int[] frame, int value) {
        for (int item : frame) {
            if (item == value) {
                return true;
            }
        }
        return false;
    }

    private static void checkAllLitModes(int[][] frames, String mode) {
        int litFrames = 0;
        for (int[] frame : frames) {
            for (int value : frame) {
                if (value > 0) {
                    litFrames++;
                    break;
                }
            }
        }
        check(litFrames > frames.length / 2, mode + " produces visible output on most frames");
    }

    private static void check(boolean condition, String message) {
        checks++;
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    private static final class AutoGenModeName {
        static String name(int mode) {
            switch (mode) {
                case AutoGen.MODE_BEATS:
                    return "Beats";
                case AutoGen.MODE_SMOOTH:
                    return "Smooth";
                case AutoGen.MODE_FREQUENCY:
                    return "Frequency";
                case AutoGen.MODE_PATTERN:
                    return "Pattern";
                default:
                    return "Mode " + mode;
            }
        }
    }
}
